#include <vector>
#include <climits>
using namespace std;

int maxSubarrayBrute(vector<int>& arr) {
    int n = arr.size();
    int maxSum = INT_MIN;

    for (int i = 0; i < n; i++) {          // every start index
        for (int j = i; j < n; j++) {      // every end index
            int currentSum = 0;

            // compute sum of subarray arr[i...j]
            for (int k = i; k <= j; k++) {
                currentSum += arr[k];
            }

            maxSum = max(maxSum, currentSum);
        }
    }

    return maxSum;
}

int main() {
    vector<int> arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};

    cout << "Maximum Subarray Sum = " << maxSubarrayBrute(arr) << endl;

    return 0;
}

