#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int kadane(vector<int>& arr) {
    int maxSum = arr[0];      // best sum seen so far
    int currentSum = arr[0];  // running sum of current subarray

    for (int i = 1; i < arr.size(); i++) {
        // Extend current subarray OR start fresh from arr[i]
        currentSum = max(arr[i], currentSum + arr[i]);

        // Update global maximum
        maxSum = max(maxSum, currentSum);
    }

    return maxSum;
}

int main() {
    vector<int> arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};

    cout << "Maximum Subarray Sum = " << kadane(arr) << endl;

    return 0;
}

