#include <iostream>
#include <vector>
using namespace std;

pair<int, vector<int>> kadaneWithIndices(vector<int>& arr) {
    int maxSum = arr[0];
    int currentSum = arr[0];

    int start = 0;       // start of best subarray
    int end = 0;         // end of best subarray
    int tempStart = 0;   // start of current subarray

    for (int i = 1; i < arr.size(); i++) {

        if (arr[i] > currentSum + arr[i]) { // restart
            currentSum = arr[i];
            tempStart = i;
        } else {                            // extend
            currentSum += arr[i];
        }

        if (currentSum > maxSum) {          // new global best
            maxSum = currentSum;
            start = tempStart;
            end = i;
        }
    }

    vector<int> subarray(arr.begin() + start, arr.begin() + end + 1);

    return {maxSum, subarray};
}

int main() {
    vector<int> arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};

    auto result = kadaneWithIndices(arr);

    cout << "Maximum Sum = " << result.first << endl;
    cout << "Subarray = ";

    for (int num : result.second)
        cout << num << " ";

    return 0;
}

