import java.util.*;

public class Main {
    public static Object[] kadaneWithIndices(int[] arr) {
        int maxSum = arr[0];
        int currentSum = arr[0];

        int start = 0;       // start of best subarray
        int end = 0;         // end of best subarray
        int tempStart = 0;   // start of current subarray

        for (int i = 1; i < arr.length; i++) {

            if (arr[i] > currentSum + arr[i]) { // restart
                currentSum = arr[i];
                tempStart = i;
            } else {                            // extend
                currentSum += arr[i];
            }

            if (currentSum > maxSum) {          // new global best
                maxSum = currentSum;
                start = tempStart;
                end = i;
            }
        }

        int[] subarray = Arrays.copyOfRange(arr, start, end + 1);

        return new Object[]{maxSum, subarray};
    }

    public static void main(String[] args) {
        int[] arr = {-2, 1, -3, 4, -1, 2, 1, -5, 4};

        Object[] result = kadaneWithIndices(arr);
        int maxSum = (int) result[0];
        int[] subarray = (int[]) result[1];

        System.out.println("Maximum Sum = " + maxSum);
        System.out.print("Subarray = ");
        for (int num : subarray) {
            System.out.print(num + " ");
        }
    }
