int kadane(vector<int>& arr) {
    if (arr.empty())
        return 0;

    int currentSum = arr[0];
    int maxSum = arr[0];

    for (int i = 1; i < arr.size(); i++) {
        // Either extend the current subarray or start fresh
        currentSum = max(arr[i], currentSum + arr[i]);

        // Update global maximum
        if (currentSum > maxSum) {
            maxSum = currentSum;
        }
    }

    return maxSum;
}

int main() {
    vector<int> arr1 = {-2, 1, -3, 4, -1, 2, 1, -5, 4};
    vector<int> arr2 = {-3, -1, -4, -2};
    vector<int> arr3 = {1, 2, 3, 4};
    vector<int> arr4 = {5};
    vector<int> arr5 = {-2, -3, 4, -1, -2, 1, 5, -3};

    cout << kadane(arr1) << endl; // 6
    cout << kadane(arr2) << endl; // -1
    cout << kadane(arr3) << endl; // 10
    cout << kadane(arr4) << endl; // 5
    cout << kadane(arr5) << endl; // 7

    return 0;
}

